<section class="card schedule-viewer" aria-label="Gymnasium schedule views">
    <header class="schedule-viewer-header"><div><h2>Gymnasium Schedule</h2><p>{{ $facilities->first()?->facility_name ?? 'Gym information unavailable' }}</p></div><nav class="schedule-view-tabs" aria-label="Schedule views">@foreach(['month' => 'Month', 'week' => 'Week', 'day' => 'Day'] as $viewKey => $viewLabel)<button type="button" @click="changeView(@js($viewKey))" :class="{ 'active': view === @js($viewKey) }" :aria-pressed="view === @js($viewKey)">{{ $viewLabel }}</button>@endforeach</nav></header>
    <div class="schedule-viewer-toolbar"><div class="schedule-view-date"><button type="button" @click="navigate(-1)" aria-label="Previous period"><i class="bi bi-chevron-left" aria-hidden="true"></i></button><label><span class="sr-only">Schedule date</span><input type="date" :value="selected" @change="pickDate($event.target.value)"></label><button type="button" @click="navigate(1)" aria-label="Next period"><i class="bi bi-chevron-right" aria-hidden="true"></i></button></div><div class="schedule-view-legend"><span><i class="available"></i>Available</span><span><i class="occupied"></i>Booked</span><span><i class="pending"></i>Pending</span><span><i class="closed"></i>Closed</span></div></div>
    @if(!$hours)<p class="schedule-warning" role="status">Operating hours are unavailable. Availability cannot be confirmed.</p>@endif
    <div x-show="view === 'month'"><h3>{{ $monthLabel }}</h3><div class="schedule-month-weekdays">@foreach(['Sun','Mon','Tue','Wed','Thu','Fri','Sat'] as $weekday)<span>{{ $weekday }}</span>@endforeach</div><div class="schedule-month-grid">
        @for($i = 0; $i < $leadingDays; $i++)<span aria-hidden="true"></span>@endfor
        @foreach($days as $date => $calendarDay)<button type="button" class="schedule-month-day {{ in_array($calendarDay['state'], ['closed', 'unknown']) ? 'closed' : ($calendarDay['approvedCount'] ? 'occupied' : ($calendarDay['pendingCount'] ? 'pending' : 'available')) }}" :class="{'selected': selected === @js($date)}" @click="selectDate(@js($date)); changeView('day')" aria-label="{{ $calendarDay['label'] }}: {{ $calendarDay['approvedCount'] }} booked, {{ $calendarDay['pendingCount'] }} pending. {{ $calendarDay['stateLabel'] }}"><strong>{{ $calendarDay['number'] }}</strong><span>{{ $calendarDay['approvedCount'] ? $calendarDay['approvedCount'].' booked' : ($calendarDay['pendingCount'] ? $calendarDay['pendingCount'].' pending' : $calendarDay['stateLabel']) }}</span>@if($calendarDay['approvedCount'] && $calendarDay['pendingCount'])<small>{{ $calendarDay['pendingCount'] }} pending</small>@endif</button>@endforeach
    </div></div>
    <div x-show="view === 'day'" x-cloak><h3>Hourly Availability — <span x-text="selected"></span></h3><p x-show="!hourRows.length" class="schedule-empty">No configured operating hours.</p><div class="schedule-hour-list"><template x-for="hour in hourRows" :key="hour.start"><div class="schedule-hour-row"><strong x-text="hour.label"></strong><div><template x-for="(segment, segmentIndex) in segmentsFor(day, hour)" :key="segmentIndex"><div class="schedule-hour-segment" :class="segment.displayState"><div><span x-text="segment.displayLabel"></span><small x-show="segment.partial" x-text="segment.time"></small><small x-show="segment.reasons.length" x-text="segment.reasons.join(' · ')"></small><div class="schedule-segment-links"><template x-for="booking in segment.bookings" :key="booking.reference"><a :href="booking.url" x-text="booking.reference + ' · ' + booking.status"></a></template></div></div><i class="bi" :class="segment.displayState === 'occupied' ? 'bi-lock' : (segment.displayState === 'pending' ? 'bi-clock' : (segment.displayState === 'available' ? 'bi-check-lg' : 'bi-slash-circle'))" aria-hidden="true"></i></div></template></div></div></template></div></div>
    <div x-show="view === 'week'" x-cloak><h3>Weekly Schedule — <span x-text="weekLabel"></span></h3><div class="schedule-week-scroll"><table class="schedule-week-table"><thead><tr><th>Time</th><template x-for="weekDay in weekDays" :key="weekDay.date"><th><button type="button" @click="changeView('day'); selectDate(weekDay.date)"><span x-text="weekDay.shortLabel"></span><small x-text="weekDay.date.slice(5)"></small></button></th></template></tr></thead><tbody><template x-for="hour in hourRows" :key="hour.start"><tr><th scope="row" x-text="hour.label"></th><template x-for="weekDay in weekDays" :key="weekDay.date"><td><template x-for="(segment, segmentIndex) in segmentsFor(weekDay, hour)" :key="segmentIndex"><div class="schedule-week-segment" :class="segment.displayState"><span x-text="segment.displayLabel"></span><small x-show="segment.partial" x-text="segment.time"></small><template x-for="booking in segment.bookings" :key="booking.reference"><a :href="booking.url" x-text="booking.reference"></a></template><small x-show="segment.reasons.length" x-text="segment.reasons.join(' · ')"></small></div></template></td></template></tr></template></tbody></table></div></div>
</section>
